const mongoose = require('mongoose');

const appointmentSchema = new mongoose.Schema({
    vetId: { type: String, required: true }, // Stores Vet ID (ObjectId or string fallback)
    petId: { type: String },
    ownerName: { type: String, required: true },
    petName: { type: String, required: true },
    petSpecies: { type: String },
    petWeight: { type: String },
    date: { type: String, required: true }, // "YYYY-MM-DD"
    time: { type: String, required: true }, // "10:00 AM"
    duration: { type: String, default: "30 Min Telehealth" },
    reason: { type: String, required: true },
    consultationType: { type: String, default: "Virtual Telehealth Call" },
    status: { type: String, enum: ['upcoming', 'today', 'urgent', 'completed', 'cancelled'], default: 'upcoming' },
    notes: { type: String },
    createdAt: { type: Date, default: Date.now }
});

module.exports = mongoose.model('Appointment', appointmentSchema);

const mongoose = require('mongoose');

const medicationSchema = new mongoose.Schema({
    name: { type: String, required: true },
    dosage: { type: String, required: true },
    frequency: { type: String, required: true },
    duration: { type: String, required: true },
    instructions: { type: String }
});

const prescriptionSchema = new mongoose.Schema({
    vetId: { type: String, required: true },
    appointmentId: { type: String },
    patientName: { type: String, required: true },
    speciesBreed: { type: String },
    ageWeight: { type: String },
    petParent: { type: String },
    symptoms: { type: String },
    diagnosis: { type: String, required: true },
    medications: [medicationSchema],
    date: { type: String }, // "September 02, 2026"
    createdAt: { type: Date, default: Date.now }
});

module.exports = mongoose.model('Prescription', prescriptionSchema);

