const express = require("express");
const router = express.Router();
const Appointment = require("../models/Appointment");
const connectDB = require("../config/db");

// Helper to check DB
function isDbAvailable() {
  return connectDB.isConnected;
}

// GET /api/appointments
// Supports filtering by vetId
router.get("/", async function (req, res) {
  try {
    const vetId = req.query.vetId;
    if (isDbAvailable() && Appointment) {
      const query = vetId ? { vetId: vetId } : {};
      const dbAppointments = await Appointment.find(query).sort({ createdAt: -1 });
      return res.json({
        success: true,
        count: dbAppointments.length,
        appointments: dbAppointments
      });
    }

    // In-memory fallback if DB not connected (empty array for now, avoiding complex shared store)
    return res.json({
      success: true,
      count: 0,
      appointments: [],
      message: "DB not available, returning empty list."
    });
  } catch(err) {
    return res.status(500).json({ success: false, message: err.message });
  }
});

// POST /api/appointments
router.post("/", async function (req, res) {
  try {
    const body = req.body;

    if (isDbAvailable() && Appointment) {
      const newAppt = await Appointment.create(body);
      return res.status(201).json({ success: true, appointment: newAppt });
    }

    // In-memory fallback
    const newAppt = { _id: "appt_" + Date.now(), ...body, createdAt: new Date() };
    return res.status(201).json({ success: true, appointment: newAppt, message: "Created in memory only" });
  } catch (err) {
    return res.status(500).json({ success: false, message: err.message });
  }
});

module.exports = router;

const express = require("express");
const router = express.Router();
const Prescription = require("../models/Prescription");
const connectDB = require("../config/db");

// Helper to check DB
function isDbAvailable() {
  return connectDB.isConnected;
}

// GET /api/prescriptions
router.get("/", async function (req, res) {
  try {
    const vetId = req.query.vetId;
    if (isDbAvailable() && Prescription) {
      const query = vetId ? { vetId: vetId } : {};
      const dbPrescriptions = await Prescription.find(query).sort({ createdAt: -1 });
      return res.json({ success: true, prescriptions: dbPrescriptions });
    }

    return res.json({ success: true, prescriptions: [], message: "DB not available" });
  } catch (err) {
    return res.status(500).json({ success: false, message: err.message });
  }
});

// POST /api/prescriptions
router.post("/", async function (req, res) {
  try {
    const body = req.body;

    if (isDbAvailable() && Prescription) {
      const newPrescription = await Prescription.create(body);
      return res.status(201).json({
        success: true,
        message: "Prescription issued successfully",
        prescription: newPrescription
      });
    }

    const newPrescription = { _id: "rx_" + Date.now(), ...body, createdAt: new Date() };

    return res.status(201).json({
        success: true,
        message: "Prescription issued successfully (Memory Mode)",
        prescription: newPrescription
    });
  } catch (err) {
    return res.status(500).json({ success: false, message: err.message });
  }
});

module.exports = router;

