// Legacy compatibility alias
window.VetAuth.protectDoctorRoute = window.VetAuth.protectRoutes;

// New asynchronous populateDoctorHeader that fetches from vets table
window.VetAuth.populateDoctorHeader = async function(user) {
  if (!user) return;

  // First, do a quick synchronous paint with whatever is in local storage (for fast perceived load)
  window.VetAuth.populateUserHeader(user);

  // Then fetch live data from the 'vets' table API
  const docId = window.VetAuth.getDoctorId(user);
  try {
    const response = await fetch(`http://localhost:5000/api/vets/${docId}`);
    if (response.ok) {
      const json = await response.json();
      if (json.success && json.data) {
        const liveUser = json.data;

        const sidebarName = document.getElementById('doctorSidebarName') || document.getElementById('sidebarDocName');
        if (sidebarName) sidebarName.textContent = liveUser.name || 'Dr. Unknown';

        const sidebarVci = document.getElementById('doctorSidebarVci');
        if (sidebarVci) sidebarVci.textContent = liveUser.vciNumber ? `VCI: ${liveUser.vciNumber}` : 'VCI Verified Specialist';

        const sidebarAvatar = document.getElementById('doctorSidebarAvatar') || document.getElementById('doctorAvatarImg');
        if (sidebarAvatar && liveUser.image) {
          sidebarAvatar.src = liveUser.image;
        } else if (sidebarAvatar && liveUser.photoUrl) {
          sidebarAvatar.src = liveUser.photoUrl;
        }
      }
    }
  } catch (e) {
    console.warn("Failed to fetch live doctor data for sidebar:", e);
  }
};

