        if (document.getElementById('metricTotalAppointments')) document.getElementById('metricTotalAppointments').textContent = m.totalAppointments || 0;
        if (document.getElementById('metricEarnings')) document.getElementById('metricEarnings').textContent = `₹${(m.monthlyEarnings || 0).toLocaleString()}`;
        if (document.getElementById('metricQueue')) document.getElementById('metricQueue').textContent = `${m.todaysConsultations || 0} Patients`; // Proxy for queue

        // Render Queue
        const queueContainer = document.getElementById('liveQueueContainer');
        if (queueContainer && json.appointments) {
            queueContainer.innerHTML = '';
            if (json.appointments.length === 0) {
                queueContainer.innerHTML = '<div class="col-span-full text-center p-8 bg-surface-container-lowest rounded-2xl border border-outline-variant/30 text-on-surface-variant font-medium">No appointments currently scheduled.</div>';
            } else {
                json.appointments.forEach(appt => {
                    const isUrgent = appt.type === 'Emergency';
                    const cardHTML = `
                    <div class="bg-surface-container-lowest rounded-2xl p-5 border border-outline-variant/30 shadow-sm relative overflow-hidden flex flex-col justify-between space-y-4 border-l-4 ${isUrgent ? 'border-l-red-500' : 'border-l-emerald-500'}">
