                            <div class="flex items-center gap-3">
                                <div class="w-12 h-12 rounded-full overflow-hidden shrink-0 border-2 border-primary/20 shadow-sm bg-primary/10 flex items-center justify-center text-primary font-bold">
                                    🐾
                                </div>
                                <div>
                                    <h4 class="font-headline-sm text-base font-bold text-on-surface">${appt.petName || 'Unknown Pet'}</h4>
                                    <p class="text-xs text-on-surface-variant font-medium">${appt.speciesBreed || 'Pet'} • ${appt.petParent || 'Owner'}</p>
                                </div>
                            </div>
                            <span class="text-[10px] font-bold ${isUrgent ? 'bg-red-100 text-red-700 border-red-200' : 'bg-emerald-100 text-emerald-800 border-emerald-200'} px-2.5 py-1 rounded-full flex items-center gap-1 border">
                                ${isUrgent ? '<span class="material-symbols-outlined text-[14px]">priority_high</span> URGENT' : '<span class="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse"></span> ' + (appt.time || 'TBA')}
                            </span>
                        </div>

                        <div class="bg-surface-container-low p-3 rounded-xl border border-outline-variant/20 text-xs">
                            <span class="font-bold ${isUrgent ? 'text-red-700' : 'text-primary'} block uppercase tracking-wider text-[10px]">Chief Complaint</span>
                            <p class="text-on-surface font-medium">${appt.reason || 'No reason provided.'}</p>
                        </div>

                        <div class="flex gap-2 pt-1">
                            <a href="prescription.html?vetId=${docId}" class="flex-1 bg-surface-container text-on-surface font-bold text-xs py-2.5 rounded-xl hover:bg-surface-container-high text-center transition-colors">
                                Rx Prescription
                            </a>
                            <a href="appointments.html" class="flex-1 ${isUrgent ? 'bg-red-600 hover:bg-red-700' : 'bg-primary hover:bg-tertiary'} text-white font-bold text-xs py-2.5 rounded-xl text-center shadow-md transition-all flex items-center justify-center gap-1">
                                <span class="material-symbols-outlined text-[16px]">${isUrgent ? 'emergency' : 'videocam'}</span> ${isUrgent ? 'Emergency Consult' : 'Join Call'}
                            </a>
                        </div>
                    </div>`;
                    queueContainer.innerHTML += cardHTML;
                });
            }
        }
    }
} catch(e) {

